demo=[[0,0,8,8,0,0,0],[8,8,8,8,8,0,0],[0,8,8,0,8,8,0],[0,8,8,8,8,0,0],[0,0,0,8,8,0,0]]
test=[[0,8,8,0,8,8,0],[8,8,8,8,8,8,0],[0,8,8,0,8,0,0],[0,0,8,8,8,0,0]]
def covers(grid):
 cells={(r,c) for r,row in enumerate(grid) for c,x in enumerate(row) if x}
 tiles=[]
 H=len(grid); W=len(grid[0])
 for r in range(H):
  for c in range(W):
   block={(r+i,c+j) for i in range(2) for j in range(2)}
   if block<=cells: tiles.append((block,('square',r,c)))
   for miss in [(0,0),(0,1),(1,0),(1,1)]:
    shape={(r+i,c+j) for i in range(2) for j in range(2) if (i,j)!=miss}
    if shape<=cells: tiles.append((shape,('L',miss,r,c)))
 sols=[]
 def rec(rem,chosen):
  if not rem: sols.append(chosen); return
  p=min(rem)
  for sh,name in tiles:
   if p in sh and sh<=rem: rec(rem-sh,chosen+[(sh,name)])
 rec(cells,[])
 return len(cells),sols
for g in [demo,test]:
 n,s=covers(g); print(n,len(s)); print([[t[1] for t in sol] for sol in s[:10]])
